css:
.bc { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 10px; font-size: 12px; letter-spacing: 0.14em; text-transform: uppercase; color: #6f8498; }
.bc-i + .bc-i::before { content: "/"; margin-right: 10px; color: #6f8498; }
.bc a { color: #9fb4c6; text-decoration: none; }
.bc a:hover { color: #00fbff; }
.bc [aria-current] { color: #00cdfd; }
